import argparse, sys, io, contextlib
def pos(v):
    try: n = int(v)
    except ValueError: raise argparse.ArgumentTypeError(f"invalid integer: {v!r}")
    if n < 1: raise argparse.ArgumentTypeError(f"must be >= 1: {v!r}")
    return n
def mk(typ=int, **kw):
    p = argparse.ArgumentParser(prog='wordstat', **kw)
    p.add_argument('--json', action='store_true')
    p.add_argument('--top', type=typ, default=10, metavar='N')
    p.add_argument('file', metavar='FILE')
    return p
def t(args, **kw):
    e = io.StringIO(); o = io.StringIO()
    try:
        with contextlib.redirect_stderr(e), contextlib.redirect_stdout(o):
            ns = mk(**kw).parse_args(args)
        print(ascii(args), '->', ascii(ns))
    except SystemExit as x:
        print(ascii(args), 'exit', x.code); print('  STDOUT:', ascii(o.getvalue()[:60])); print('  STDERR:', ascii(e.getvalue()))
